<article class="card overflow-hidden"><a href="{{route('product',$item)}}" class="block"><div class="photo">@if($item->images->first())<img loading="lazy" src="{{asset('storage/'.$item->images->first()->path)}}" alt="{{$item->images->first()->alt}}" @if($item->demoImageUrl()) onerror="this.onerror=null;this.src='{{$item->demoImageUrl()}}'" @endif>@elseif($item->demoImageUrl())<img loading="lazy" src="{{$item->demoImageUrl()}}" alt="Illustrative photo of {{$item->name}}">@else<span class="serif text-3xl opacity-70">{{$item->category?->name ?? 'Jewellery'}}</span>@endif</div><div class="p-4"><p class="text-xs uppercase tracking-widest gold mb-2">{{$item->category?->name}}</p><h3 class="text-lg serif">{{$item->name}}</h3><p class="mt-2 price text-sm">From ₹{{number_format(($item->variants->min('price_paise')??0)/100,2)}}</p></div></a></article>
